import { createSourcePrefetchMigration } from "data:text/javascript;base64,";
import { createPersistentMigrationDatabase, createInProcessMigrationCli } from "data:text/javascript;base64,";
import { createPacedMigrationTransport } from "data:text/javascript;base64,";
import { createMigrationTransportRetries } from "data:text/javascript;base64,";
import { createDiagnosticMigrationDatabaseFactory } from "data:text/javascript;base64,";

export function createOptimisedMigrationRuntime({ runCatalogueR2Migration, migrateCatalogueAssets,
  planCatalogueAssetMigration, createClient, storage, fetchImpl = globalThis.fetch,
  report = value => console.log(JSON.stringify(value)), prefetchEnabled = true,
  signal, terminate, sourceOrigin = 'https://oakdbbzdqwurpjnoqhmu.supabase.co', cdnOrigin = 'https://assets.stackrtcg.com' } = {}) {
  const database = createPersistentMigrationDatabase({ createClient, createDiagnosticMigrationDatabaseFactory, report });
  const paced = createPacedMigrationTransport({ fetchImpl, storage, sourceOrigin, cdnOrigin, report });
  const retries = createMigrationTransportRetries({ report });
  const configuredStorage = retries.storage(paced.storage);
  const publicFetch = retries.fetch(paced.fetch);
  const migration = createSourcePrefetchMigration({ migrateCatalogueAssets, planCatalogueAssetMigration,
    enabled: prefetchEnabled, report });
  const runCli = createInProcessMigrationCli({ runCatalogueR2Migration, createDb: database.createDb,
    createStorage: () => configuredStorage, fetchImpl: publicFetch, migrate: migration, report, signal, drain: paced.drain,
    ...(terminate ? { terminate } : {}) });
  return { runCli, async close() { await paced.drain(); await database.close(); },
    metrics: () => ({ database: database.metrics(), transport: paced.metrics() }) };
}
